function phase5Api(string $entity,string $method = 'GET',?array $data = null,string $client = 'admin',int $status = 200): array {
	$response=phase3Api(str_starts_with($entity,'/api/') ? $entity : '/api/operations/'.$entity,$method,$data,$client);
	verify($response['status']===$status || ($status===200 && $response['status']===201),$method.' '.$entity.' esperaba '.$status.': '.$response['body']);
	return $response['json']['data'] ?? [];
}
